--!strict
--!optimize 2

--[=[
	Events: what goes into step and what comes out of it. An Event is the clock reading and what happened. A
	Command asks the shell for one DataStore request, a MemoryStore get, set, update or remove, a JSON decode, a counter
	add, a wake, a Ready, an answer, an observer value or a warning. The core decodes update values.

	Return type: An empty table. The types are Event, Happening, Call, GivenName, ReadMethod, ReadAnswered,
	ReadOutcome, MemoryFetched, Outcome, MemoryOutcome, DecodeOutcome, Answer, Command and each of its variants
	(UpdateCommand to WarnCommand), TxCall, PendingCall and ResettleCall.
	Example usage:
		local Events = require("./Events")
		type Event = Events.Event
--]=]

local Book = require("../Keys/Format/Book")
local CutShapes = require("./ResetShapes")
local ExtrasShapes = require("./ReadShapes")
local Fates = require("../Keys/Format/Items/Fates")
local HotShapes = require("./QuantityShapes")
local JudgingShapes = require("./OpShapes")
local Names = require("../Keys/Encoding/Names")
local Reasons = require("../Keys/Constants/Reasons")
local Shapes = require("./Shapes")
local TxShapes = require("./TradeShapes")

type Identity = Book.Identity
type PartReason = Fates.PartReason
type StoreKey = Names.StoreKey
type Reason = Reasons.Reason
type AskedName = Shapes.AskedName
type Request = Shapes.Request
type Note = JudgingShapes.Note

export type ReadAnswered = { read Kind: "Found", read Value: unknown } | { read Kind: "Absent" }

export type ReadOutcome = ReadAnswered | { read Kind: "Failed", read IsThrottled: boolean }

export type MemoryFetched = ReadAnswered | { read Kind: "Failed" }

export type Outcome =
	{ read Kind: "Ok", read Value: unknown, read Note: Note }
	| { read Kind: "Nil", read Note: Note }
	| { read Kind: "Err" }

export type MemoryOutcome = { read Kind: "Ok", read Value: unknown } | { read Kind: "Nil" } | { read Kind: "Err" }

export type DecodeOutcome = { read Kind: "Found", read Value: unknown } | { read Kind: "Failed" }

export type GivenName = Names.GivenName

export type TxCall = {
	read Kind: "Call",
	read Method: "Tx",
	read CallId: number,
	read Legs: { TxShapes.TxLeg },
	read Hot: number?,
	read Name: GivenName?,
}

export type PendingCall = { read Kind: "Call", read Method: "Pending", read CallId: number, read Key: StoreKey }

export type ResettleCall = {
	read Kind: "Call",
	read Method: "Resettle",
	read CallId: number,
	read Key: StoreKey,
}

export type ReadMethod = "Peek" | "Inspect" | "PeekFresh" | "Losses"

export type Call =
	{ read Kind: "Call", read Method: "Id", read CallId: number }
	| { read Kind: "Call", read Method: "CloseAll", read CallId: number, read BeganAt: number? }
	| { read Kind: "Call", read Method: "Load", read CallId: number, read Key: StoreKey, read MustExist: boolean }
	| {
		read Kind: "Call",
		read Method: "Apply",
		read CallId: number,
		read Key: StoreKey,
		read OpKind: string,
		read Terms: unknown,
	}
	| {
		read Kind: "Call",
		read Method: "Edit",
		read CallId: number,
		read Key: StoreKey,
		read OpKind: string,
		read Terms: unknown,
		read MustExist: boolean,
		read Name: GivenName?,
	}
	| {
		read Kind: "Call",
		read Method: "Commit",
		read CallId: number,
		read Key: StoreKey,
		read OpKind: string,
		read Terms: unknown,
		read Name: GivenName?,
	}
	| { read Kind: "Call", read Method: "Flush", read CallId: number, read Key: StoreKey }
	| { read Kind: "Call", read Method: "Refresh", read CallId: number, read Key: StoreKey }
	| { read Kind: "Call", read Method: "Release", read CallId: number, read Key: StoreKey }
	| { read Kind: "Call", read Method: ReadMethod, read CallId: number, read Key: StoreKey }
	| { read Kind: "Call", read Method: "DidApply", read CallId: number, read Key: StoreKey, read Name: AskedName }
	| {
		read Kind: "Call",
		read Method: "DidApplyWithProbe",
		read CallId: number,
		read Key: StoreKey,
		read Name: AskedName,
	}
	| TxCall
	| PendingCall
	| ResettleCall
	| CutShapes.EraseCall
	| CutShapes.ResetCall
	| ExtrasShapes.BumpCall
	| ExtrasShapes.TotalCall
	| ExtrasShapes.FollowCall
	| ExtrasShapes.UnfollowCall
	| ExtrasShapes.StaleCall
	| ExtrasShapes.PeekWithinCall
	| HotShapes.TakeCall
	| HotShapes.GatherCall
	| HotShapes.HoldCall
	| HotShapes.OpenCall
	| HotShapes.CloseCall
	| HotShapes.ConfirmCall
	| HotShapes.ReleaseCall
	| HotShapes.DepositCall
	| HotShapes.WithdrawCall

export type Happening =
	Call
	| { read Kind: "Result", read RequestId: number, read Outcome: Outcome }
	| { read Kind: "Read", read RequestId: number, read Fetched: ReadOutcome, read Fraction: number }
	| { read Kind: "MemoryRead", read RequestId: number, read Fetched: MemoryFetched, read Fraction: number }
	| { read Kind: "MemoryResult", read RequestId: number, read Outcome: MemoryOutcome }
	| { read Kind: "Decoded", read RequestId: number, read Outcome: DecodeOutcome }
	| { read Kind: "Removed", read RequestId: number, read IsOk: boolean }
	| { read Kind: "Send", read Key: StoreKey }
	| { read Kind: "Clock" }
	| { read Kind: "Counted", read RequestId: number, read Written: string? }
	| { read Kind: "CounterUnusable", read RequestId: number }

export type Event = {
	read Clock: number,
	read Happening: Happening,
}

export type Answer =
	{ read Kind: "Succeeded", read Value: unknown }
	| {
		read Kind: "Failed",
		read Reason: Reason,
		read State: unknown,
		read Identity: Identity?,
		read Name: GivenName?,
		read ShortReason: PartReason?,
		read Key: StoreKey?,
	}

export type UpdateCommand = {
	read Kind: "Update",
	read RequestId: number,
	read Target: StoreKey,
	read Request: Request,
	read Candidate: { [unknown]: unknown }?,
}

export type GetCommand = { read Kind: "Get", read RequestId: number, read Target: StoreKey }

export type CountCommand = {
	read Kind: "Count",
	read RequestId: number,
	read Target: StoreKey,
	read Add: (Stored: unknown) -> string?,
}

export type RemoveCommand = { read Kind: "Remove", read RequestId: number, read Target: StoreKey }

export type MemoryUpdateCommand = {
	read Kind: "MemoryUpdate",
	read RequestId: number,
	read Map: string,
	read Key: string,
	read Item: (Current: unknown, Clock: number) -> unknown?,
	read Expiry: number,
}

export type MemoryGetCommand = { read Kind: "MemoryGet", read RequestId: number, read Map: string, read Key: string }

export type MemorySetCommand = {
	read Kind: "MemorySet",
	read RequestId: number,
	read Map: string,
	read Key: string,
	read Item: unknown,
	read Expiry: number,
}

export type MemoryRemoveCommand = {
	read Kind: "MemoryRemove",
	read RequestId: number,
	read Map: string,
	read Key: string,
}

export type DecodeCommand = { read Kind: "Decode", read RequestId: number, read Text: string }

export type WakeCommand = { read Kind: "Wake", read At: number }

export type AnswerCommand = { read Kind: "Answer", read CallId: number, read Answer: Answer }

export type EmitCommand = { read Kind: "Emit", read Stream: string, read Key: StoreKey, read Value: unknown }

export type ReadyCommand = { read Kind: "Ready", read Key: StoreKey }

export type WarnCommand = { read Kind: "Warn", read Key: StoreKey?, read Text: string }

export type Command =
	UpdateCommand
	| GetCommand
	| CountCommand
	| RemoveCommand
	| MemoryUpdateCommand
	| MemoryGetCommand
	| MemorySetCommand
	| MemoryRemoveCommand
	| DecodeCommand
	| WakeCommand
	| AnswerCommand
	| EmitCommand
	| ReadyCommand
	| WarnCommand

return {}

--!strict
--!optimize 2

--[=[
	Shapes: what judging a request gives back: the report each op gets, the note the request leaves with what its
	closure wrote and ran, a reducer's verdict and an op's judged fate.

	A report a protocol owns is imported from that protocol's Shapes. A write's working state is in Judging/Run.
	Unreadable's Amounts cause lies beside the value, not in it.

	Return type: An empty table. The types are Closure, Shortage, UnreadableCause, EndWorkReport, Report, NoteWarning,
	Note, Verdict and Judged.
	Example usage:
		local OpShapes = require("./Shared/OpShapes")
		type Report = OpShapes.Report
--]=]

local Book = require("../Keys/Format/Book")
local CutShapes = require("./ResetShapes")
local Fates = require("../Keys/Format/Items/Fates")
local Names = require("../Keys/Encoding/Names")
local Seal = require("../Keys/Format/Items/Seal")
local TxShapes = require("./TradeShapes")
local Value = require("../Keys/Format/Value")
local Work = require("../Keys/Format/Items/Work")

type Identity = Book.Identity
type Value = Value.Value
type Kept = Value.Kept
type Fate = Fates.Fate
type PartReason = Fates.PartReason
type Name = Names.Name
type Mark = Work.Mark
type Gate = Seal.Gate
type Seal = Seal.Seal

export type Closure = {
	Wrote: boolean,
	Ran: { [number]: boolean },
}

export type Shortage = { read Items: number, read Bytes: number }

export type UnreadableCause = Value.UnreadableCause | "Balance" | "Amounts"

export type EndWorkReport =
	{ read Kind: "NoRoom", read Marks: { Mark }, read Short: Shortage? }
	| { read Kind: "Overdue", read Marks: { Mark } }
	| { read Kind: "Blocked", read Marks: { Mark } }

export type Report =
	EndWorkReport
	| { read Kind: "Fated", read Fate: Fate, read State: unknown }
	| { read Kind: "Cut" }
	| { read Kind: "Spent" }
	| { read Kind: "Forgotten" }
	| { read Kind: "Landed" }
	| { read Kind: "Behind" }
	| { read Kind: "Ahead" }
	| {
		read Kind: "Missing",
		read Identity: Identity?,
		read Seal: Seal?,
		read IsLeftOver: boolean,
		read IsLegacy: boolean,
	}
	| { read Kind: "Undecided" }
	| { read Kind: "Unreadable", read Cause: UnreadableCause }
	| { read Kind: "Worn" }
	| { read Kind: "Owed", read Marks: { Mark } }
	| { read Kind: "Gated", read Gate: Gate }
	| { read Kind: "GatedBy", read Gate: Gate, read Marks: { Mark } }
	| { read Kind: "Marks", read Marks: { Mark } }
	| { read Kind: "Wait", read At: number }
	| { read Kind: "Gone" }
	| { read Kind: "Sealed", read Seal: Seal }
	| { read Kind: "Invalid" }
	| CutShapes.CutReport
	| TxShapes.TxReport

export type NoteWarning =
	{ read Kind: "AlsoCut", read Name: Name }
	| { read Kind: "CreatedAfterErase" }
	| { read Kind: "UnnamedBalance", read Field: string }
	| { read Kind: "WrittenBeforeErasable" }

export type Note = {
	read Reports: { Report },
	read Writes: number,
	read Cuts: number,
	read Horizon: number,
	read CutHorizon: number,
	read Identity: Identity?,
	read ShowsKey: boolean,
	read Closure: Closure,
	read State: unknown,
	read WrittenValue: Value?,
	read ReadValue: Kept?,
	read WrittenBytes: number?,
	read WrittenStateBytes: number?,
	read ProbeReport: Report?,
	read Warnings: { NoteWarning },
	read EndReports: { Report },
	read Work: { Mark },
	read Gate: Gate?,
}

export type Verdict =
	{ read Kind: "Took", read State: { [unknown]: unknown } }
	| { read Kind: "TookWith", read State: { [unknown]: unknown }, read Value: number }
	| { read Kind: "RefusedFor", read Reason: PartReason }
	| { read Kind: "NoState" }
	| { read Kind: "Unstorable" }
	| { read Kind: "Refused" }
	| { read Kind: "Full" }
	| { read Kind: "Unreadable" }
	| { read Kind: "Invalid" }
	| { read Kind: "InvalidBalance" }

export type Judged = Fate | { read Kind: "Unreadable" } | { read Kind: "Invalid" }

return {}

--!strict
--!optimize 2

--[=[
	Shapes: the shapes a transaction puts in a request, an end, a note and a report (transaction sheet 4).

	A Tent or a Commit is an op form that carries its leg. Each End, a Resolve, a Drop or a Fence, has one report in
	Note.EndReports. A Refused report carries the state its transform read, none from a stored fate.

	Return type: An empty table. The types are TxLeg, DeltaLeg, GameLeg, LegForm, TentForm, CommitForm, TxOutcome,
	DroppedName, ResolveEnd, DropEnd, FenceEnd, End, TxReport, Carrier, HeldEnd and AbortedUse.
	Example usage:
		local TradeShapes = require("./Shared/TradeShapes")
		type End = TradeShapes.End
--]=]

local Fates = require("../Keys/Format/Items/Fates")
local Names = require("../Keys/Encoding/Names")
local Post = require("../Keys/Format/Post")

type Fate = Fates.Fate
type KeyReference = Names.KeyReference
type OpName = Names.OpName
type StoreKey = Names.StoreKey
type PathStep = Post.PathStep

export type TxLeg = {
	read Key: StoreKey,
	read OpKind: string,
	read Terms: unknown,
	read MustExist: boolean?,
	read Slot: { PathStep }?,
}

export type DeltaLeg = { read Kind: "Delta", read Field: string, read IsDebit: boolean, read Amount: unknown }

export type GameLeg = { read Kind: "Game", read Slot: { PathStep }? }

export type LegForm = DeltaLeg | GameLeg

export type TentForm = {
	read Kind: "Tent",
	read Name: OpName,
	read Attempt: number,
	read Leg: LegForm,
	read Decider: KeyReference,
}

export type CommitForm = {
	read Kind: "Commit",
	read Name: OpName,
	read Attempt: number,
	read Leg: LegForm,
	read OtherLegs: { KeyReference },
}

export type TxOutcome = "Commit" | "Abort" | "Orphan"

export type DroppedName = {
	read Name: OpName,
	read Stamp: number,
	read Proved: KeyReference?,
}

export type ResolveEnd = {
	read Kind: "Resolve",
	read Name: OpName,
	read Stamp: number,
	read Attempt: number,
	read Outcome: TxOutcome,
	read Decider: KeyReference,
	read DeciderValue: number?,
}

export type DropEnd = { read Kind: "Drop", read Names: { DroppedName } }

export type FenceEnd = {
	read Kind: "Fence",
	read Name: OpName,
	read Stamp: number,
	read Attempt: number,
	read IsFinal: boolean,
}

export type End = ResolveEnd | DropEnd | FenceEnd

export type TxReport =
	{ read Kind: "Mine", read Attempt: number }
	| { read Kind: "Superseded", read Attempt: number }
	| { read Kind: "Decided", read Fate: Fate }
	| { read Kind: "Other" }
	| { read Kind: "Refused", read Fate: Fate, read State: unknown }
	| { read Kind: "Large" }
	| { read Kind: "Committed", read Attempt: number, read DeciderValue: number? }
	| { read Kind: "Fenced", read Attempt: number, read IsFinal: boolean }
	| { read Kind: "Done" }
	| { read Kind: "Proved", read RemovalStamp: number, read Sealer: number }
	| { read Kind: "Exists" }
	| { read Kind: "Served", read Part: number }

export type Carrier =
	{ read Kind: "Writer", read Key: StoreKey }
	| { read Kind: "Call", read CallId: number }
	| { read Kind: "Touch", read Key: StoreKey }
	| { read Kind: "Resettle", read CallId: number }
	| { read Kind: "Cut", read CallId: number }

export type HeldEnd = {
	read End: End,
	read CallId: number?,
	read Until: number?,
	read For: Carrier?,
}

export type AbortedUse = { read Name: OpName, read Attempt: number }

return {}
